from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); frames=[]
    colors=set(x for row in grid for x in row if x)
    for color in colors:
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=color or (r,c) in seen: continue
                q=[(r,c)]; seen.add((r,c)); comp=[]
                while q:
                    y,x=q.pop(); comp.append((y,x))
                    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                            seen.add((yy,xx));q.append((yy,xx))
                r0=min(y for y,x in comp);r1=max(y for y,x in comp)
                c0=min(x for y,x in comp);c1=max(x for y,x in comp)
                if r1-r0<2 or c1-c0<2: continue
                border={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1) if y in (r0,r1) or x in (c0,c1)}
                if set(comp)==border:
                    frames.append((color,r0,r1,c0,c1,border))
    if not frames: return [row[:] for row in grid]
    # Colors appearing on frame borders are structural, all remaining colors are candidate pattern colors.
    frame_cells=set().union(*(f[5] for f in frames))
    counts=Counter(grid[r][c] for r in range(h) for c in range(w) if grid[r][c] and (r,c) not in frame_cells)
    output=[[0]*w for _ in range(h)]
    for color,r0,r1,c0,c1,border in frames:
        for r,c in border: output[r][c]=color
        ir0,ir1,ic0,ic1=r0+1,r1-1,c0+1,c1-1
        n=sum(1 for r in range(ir0,ir1+1) for c in range(ic0,ic1+1) if (r-ir0+c-ic0)%2==0)
        # choose the non-structural color whose stray-pixel count matches this checker pattern
        candidates=[col for col,count in counts.items() if col not in {f[0] for f in frames} and count==n]
        if candidates:
            fill=candidates[0]
            for r in range(ir0,ir1+1):
                for c in range(ic0,ic1+1):
                    if (r-ir0+c-ic0)%2==0: output[r][c]=fill
    return output
